import csv

# Check: how many loyalty customers have a canonical tier but empty discount?
TIER_MAP = {
    "Bronz": "Bronze", "Bronze": "Bronze", "bronze": "Bronze",
    "Sliver": "Silver", "Silver": "Silver", "silver": "Silver",
    "Goald": "Gold", "Gold": "Gold", "gold": "Gold",
    "": None,
}

tier_no_disc = 0
with open("data/loyalty_customers.csv", newline="") as f:
    reader = csv.DictReader(f)
    for row in reader:
        tier_raw = row["Loyalty_Tier"].strip()
        tier = TIER_MAP.get(tier_raw)
        disc = row["Loyalty_Discount"].strip()
        if tier is not None and disc == "":
            tier_no_disc += 1

print(f"Customers with canonical tier but empty discount: {tier_no_disc}")

# Now check how many transaction rows in 2023/2024 hit these customers
from datetime import datetime

def parse_date(raw):
    try:
        return datetime.strptime(raw.strip(), "%a, %B %d, %Y")
    except ValueError:
        return None

def normalize_loyalty_number(raw):
    raw = raw.strip()
    if raw.endswith(".0"):
        return raw[:-2]
    return raw

# Build set of loyalty numbers with tier but no discount
no_disc_lnums = set()
with open("data/loyalty_customers.csv", newline="") as f:
    reader = csv.DictReader(f)
    for row in reader:
        tier_raw = row["Loyalty_Tier"].strip()
        tier = TIER_MAP.get(tier_raw)
        disc = row["Loyalty_Discount"].strip()
        if tier is not None and disc == "":
            no_disc_lnums.add(row["Loyalty_Number"].strip())

rows_with_missing_disc = 0
with open("data/transactions.csv", newline="") as f:
    reader = csv.DictReader(f)
    for row in reader:
        dt = parse_date(row["Transaction_Date"])
        if dt is None or dt.year not in (2023, 2024):
            continue
        ln_norm = normalize_loyalty_number(row["Loyalty_Number"].strip())
        if ln_norm in no_disc_lnums:
            rows_with_missing_disc += 1

print(f"2023/2024 transaction rows with canonical tier but missing discount: {rows_with_missing_disc}")
PYEOF"}
